# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">HÜZÜN YILI\'NDAN İSRÂ VE MİRAÇ MUCİZESİNE (PH.10.2.1)</text>\n  <rect x="20" y="42" width="210" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. HÜZÜN YILI VE TAİF</text>\n  <text x="32" y="88" font-size="10.8" fill="#1e3a8a">• 3 yıllık boykotun ardından</text>\n  <text x="40" y="104" font-size="10.5" fill="#1e3a8a">nübüvvetin 10. yılında (620)</text>\n  <text x="40" y="120" font-size="10.5" fill="#1e3a8a">Ebû Tâlib ve Hz. Hatice\'nin</text>\n  <text x="40" y="136" font-size="10.5" fill="#1e3a8a">vefatı (Senetü\'l-Hüzün).</text>\n  <text x="32" y="160" font-size="10.8" fill="#1e3a8a">• Zorlu Taif yolculuğu sonrası</text>\n  <text x="40" y="176" font-size="10.5" fill="#1e3a8a">Rabbine sığınış ve ilahi teselli.</text>\n  <rect x="245" y="42" width="210" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. İSRÂ (GECE YÜRÜYÜŞÜ)</text>\n  <text x="257" y="88" font-size="10.8" fill="#14532d">• Mekke\'deki Mescid-i Harâm\'dan</text>\n  <text x="265" y="104" font-size="10.5" fill="#14532d">Kudüs\'teki Mescid-i Aksâ\'ya</text>\n  <text x="265" y="120" font-size="10.5" fill="#14532d">gece vakti yapılan yolculuk.</text>\n  <text x="257" y="144" font-size="10.8" fill="#14532d">• İsrâ suresi 1. ayetle sabittir.</text>\n  <text x="257" y="168" font-size="10.8" fill="#14532d">• Peygamberlere Mescid-i Aksâ\'da</text>\n  <text x="265" y="184" font-size="10.5" fill="#14532d">imamlık (tevhid halkası).</text>\n  <rect x="470" y="42" width="210" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="575" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">3. MİRAÇ (YÜKSELİŞ)</text>\n  <text x="482" y="88" font-size="10.8" fill="#581c87">• Mescid-i Aksâ\'dan göklere ve</text>\n  <text x="490" y="104" font-size="10.5" fill="#581c87">Sidretü\'l-Müntehâ makamına</text>\n  <text x="490" y="120" font-size="10.5" fill="#581c87">yükseliş (Necm, 1-18).</text>\n  <text x="482" y="144" font-size="10.8" fill="#581c87">• Hz. Ebû Bekir\'in tereddütsüz</text>\n  <text x="490" y="160" font-size="10.5" fill="#581c87">tasdiki: "O söylediyse doğrudur"</text>\n  <text x="490" y="176" font-size="10.5" font-weight="bold" fill="#581c87">⟶ "es-Sıddîk" unvanı.</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">İsrâ ve Miraç, Mekke ile Kudüs\'ü (Mescid-i Harâm ile Mescid-i Aksâ\'yı) kıyamete kadar birbirine bağlamıştır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">MİRAÇ GECESİNİN ÜÇ BÜYÜK İLAHİ HEDİYESİ</text>\n  <rect x="20" y="42" width="210" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="125" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">1. BEŞ VAKİT NAMAZ</text>\n  <text x="32" y="90" font-size="10.8" fill="#78350f">• Günde 5 vakit namaz (sevabı</text>\n  <text x="40" y="106" font-size="10.5" fill="#78350f">50 vakte denk) aracısız olarak</text>\n  <text x="40" y="122" font-size="10.5" fill="#78350f">bizzat Miraç gecesi farz kılındı.</text>\n  <text x="32" y="148" font-size="10.8" font-weight="bold" fill="#78350f">• "Namaz müminin miracıdır"</text>\n  <text x="40" y="164" font-size="10.5" fill="#78350f">hikmetiyle kulun günde beş kez</text>\n  <text x="40" y="180" font-size="10.5" fill="#78350f">Rabbiyle buluşma makamıdır.</text>\n  <rect x="245" y="42" width="210" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="350" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#065f46">2. ÂMENERRASÛLÜ AYETLERİ</text>\n  <text x="257" y="90" font-size="10.8" fill="#064e3b">• Bakara suresinin son iki ayeti</text>\n  <text x="265" y="106" font-size="10.5" fill="#064e3b">(285 ve 286. ayetler) verildi.</text>\n  <text x="257" y="132" font-size="10.8" fill="#064e3b">• İman esaslarının özeti,</text>\n  <text x="265" y="148" font-size="10.5" fill="#064e3b">"İşittik ve itaat ettik" teslimiyeti</text>\n  <text x="265" y="164" font-size="10.5" fill="#064e3b">ve Allah\'ın kimseye gücünün</text>\n  <text x="265" y="180" font-size="10.5" fill="#064e3b">üstünde yük yüklemeyeceği duası.</text>\n  <rect x="470" y="42" width="210" height="175" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="575" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">3. ŞİRKSİZ ÖLENE AF MÜJDESİ</text>\n  <text x="482" y="90" font-size="10.8" fill="#881337">• Ümmetten Allah\'a hiçbir şeyi</text>\n  <text x="490" y="106" font-size="10.5" fill="#881337">ortak (şirk) koşmadan vefat</text>\n  <text x="490" y="122" font-size="10.5" fill="#881337">eden kimselerin büyük</text>\n  <text x="490" y="138" font-size="10.5" fill="#881337">günahlarının bağışlanabileceği</text>\n  <text x="490" y="154" font-size="10.5" fill="#881337">ve sonunda cennete gireceği</text>\n  <text x="490" y="170" font-size="10.5" font-weight="bold" fill="#881337">ilahi rahmet müjdesi verildi.</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">İsrâ suresi 23-39. ayetlerde tevhid, anne babaya iyilik, akrabava/yoksula yardım ve adalet ilkeleri bildirildi.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">HADİS-İ ŞERİFLERDE KUDÜS VE MESCİD-İ AKSÂ (PH.10.2.2)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#1e40af">ÜÇ MESCİT VE NAMAZ FAZİLETİ HADİSLERİ</text>\n  <text x="35" y="88" font-size="10.8" fill="#1e3a8a">• "İbadet kastıyla yolculuk ancak üç mescide yapılır:</text>\n  <text x="45" y="104" font-size="10.5" font-weight="bold" fill="#1e3a8a">Mescid-i Harâm, benim bu mescidim (Mescid-i</text>\n  <text x="45" y="120" font-size="10.5" font-weight="bold" fill="#1e3a8a">Nebevî) ve Mescid-i Aksâ." (Buhârî; Müslim)</text>\n  <text x="35" y="146" font-size="10.8" fill="#1e3a8a">• Yeryüzünde المَسْجِدُ الْحَرَامِ\'dan sonra inşa edilen</text>\n  <text x="45" y="162" font-size="10.5" fill="#1e3a8a">ikinci mescit Mescid-i Aksâ\'dır (Ebû Zer hadisi).</text>\n  <text x="35" y="186" font-size="10.8" fill="#1e3a8a">• Müslümanların yöneldiği ilk kıble (Ûlâ\'l-Kıbleteyn).</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#9a3412">HZ. MEYMÛNE (R.A.) VE KANDİL HADİSİ</text>\n  <text x="370" y="88" font-size="10.8" fill="#7c2d12">• Hz. Meymûne: "Yâ Resûlallah! Bize Beytülmakdis</text>\n  <text x="380" y="104" font-size="10.5" fill="#7c2d12">hakkında fetva (bilgi/tavsiye) ver!" diye sordu.</text>\n  <text x="370" y="128" font-size="10.8" fill="#7c2d12">• Hz. Peygamber (s.a.v.) buyurdu ki:</text>\n  <text x="380" y="144" font-size="10.5" font-weight="bold" fill="#7c2d12">"Orası mahşer ve neşir (toplanma) yeridir.</text>\n  <text x="380" y="160" font-size="10.5" font-weight="bold" fill="#7c2d12">Oraya gidin ve içinde namaz kılın! Eğer oraya</text>\n  <text x="380" y="176" font-size="10.5" font-weight="bold" fill="#7c2d12">gidemezseniz kandillerinde yakılmak üzere</text>\n  <text x="380" y="192" font-size="10.5" font-weight="bold" fill="#7c2d12">oraya zeytinyağı gönderin!" (Ebû Dâvûd; İbn Mâce)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Kandillerine yağ gönderme emri, Mescid-i Aksâ\'yı maddi-manevi ihya etme ve Kudüs nöbetini sürdürme bilincidir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
